/** Pakowanie Zebra dla taśm = 12 szt./karton (standard producenta).
 *
 *  Zaobserwowany wzorzec źródeł cenowych (po analizie 5 PN-ów):
 *  - **Ingram Micro PL** — zwraca cenę za 1 sztukę (poprawnie). Brak niektórych PN-ów.
 *  - **BlueStar EU** — zwraca cenę za **12-pak** (pakiet) niezależnie od PN. EUR.
 *  - **Jarltech** — analogicznie do BlueStar (zazwyczaj pakiet).
 *
 *  W konsekwencji `/api/stock` dla taśm dzieli BlueStar i Jarltech przez 12 przed
 *  obliczeniem `min(...)`. Lista PN-ów taśm potrzebna w tym module + UI gdy chcemy
 *  jednoznacznie rozpoznać taśmę po PN.
 */
export const RIBBON_PACKAGING_QTY = 12

/** Set wszystkich PN-ów taśm w katalogu — używany w `/api/stock` do detekcji pakietowych
 *  źródeł cenowych. Zbudowany leniwie z `rawRibbonProducts`. */
let _ribbonPNs: Set<string> | null = null
export function getAllRibbonPartNumbers(): Set<string> {
  if (_ribbonPNs) return _ribbonPNs
  const s = new Set<string>()
  for (const p of rawRibbonProducts) {
    for (const v of (p.variants ?? [])) s.add(v.partNumber)
  }
  _ribbonPNs = s
  return s
}

export function isRibbonPN(partNumber: string): boolean {
  return getAllRibbonPartNumbers().has(partNumber)
}

/** Dedup wariantów per PN w obrębie serii — zachowuje wpis z najpełniejszymi atrybutami. */
function dedupVariants(variants: ProductVariant[] | undefined): ProductVariant[] | undefined {
  if (!variants) return variants
  const byPn = new Map<string, ProductVariant>()
  for (const v of variants) {
    const existing = byPn.get(v.partNumber)
    if (!existing) {
      byPn.set(v.partNumber, v)
      continue
    }
    const existingAttrs = Object.keys(existing.attributes).length
    const candidateAttrs = Object.keys(v.attributes).length
    if (candidateAttrs > existingAttrs) byPn.set(v.partNumber, v)
  }
  return Array.from(byPn.values())
}

/** Zachowane dla wstecznej kompatybilności — komponent może to sprawdzić, ale aktualnie
 *  korekta cen odbywa się tylko adaptacyjnie w backendzie (`/api/stock`). */
export function isRibbonPackagedByDozenPN(_partNumber: string): boolean {
  return false
}

export const transferRibbonProducts: Product[] = rawRibbonProducts.map((p) => ({
  compatibleAccessories: [],
  downloads: [],
  createdAt: '2026-05-30',
  ...p,
  variants: dedupVariants(p.variants),
}))
